    m0, m1 = ld(f"structfc_m1g_{per}_price", "vint_ts"), ld(f"structfc_m1m_{per}_price", "vint_ts"); c0, c1 = ld(f"structfc_{r0}_ts_dyn2xxh"), ld(f"structfc_{r1}_ts_dyn2xxh"); mk = ld(f"structfc_m1m_{per}_price"); g0, g1 = np.load(f"{SP}/out/gen_ts_{per}.npz"), np.load(f"{SP}/out/gen_mid_{per}.npz"); le = lambda g: np.abs(g["rl_pes"].astype(float) - g["rl_true"].astype(float))[:, SL].mean(1)
